create view "test"."companies_summary"
    with (security_invoker=on)
    as
select 
    c.*,
    count(distinct d.id) as nb_deals,
    count(distinct co.id) as nb_contacts
from 
    "test"."companies" c
left join 
    "test"."deals" d on c.id = d.company_id
left join 
    "test"."contacts" co on c.id = co.company_id
group by 
    c.id;

-- Use Postgres to create views for contacts.

create view "test"."contacts_summary"
    with (security_invoker=on)
    as
select 
    co.*,
    c.name as company_name,
    count(distinct t.id) as nb_tasks
from
    "test"."contacts" co
left join
    "test"."tasks" t on co.id = t.contact_id
left join
    "test"."companies" c on co.company_id = c.id
group by
    co.id, c.name;


create function test.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
declare
  sales_count int;
begin
  select count(id) into sales_count
  from test.sales;

  insert into test.sales (first_name, last_name, email, user_id, administrator)
  values (
    new.raw_user_meta_data ->> 'first_name', 
    new.raw_user_meta_data ->> 'last_name', 
    new.email, 
    new.id, 
    case when sales_count > 0 then FALSE else TRUE end
  );
  return new;
end;
$$;

create function test.handle_update_user()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  update test.sales
  set 
    first_name = new.raw_user_meta_data ->> 'first_name', 
    last_name = new.raw_user_meta_data ->> 'last_name', 
    email = new.email
  where user_id = new.id;

  return new;
end;
$$;


